-- =====================================================================
-- TrustStack DPDP - MASTER database setup  (generated 2026-06-22)
-- One table per question set:
--   quiz_questions   = 50  (DPDP knowledge quiz, has difficulty + category)
--   exam_questions   = 224 (Certificate Exam, modules 1-6, derived difficulty)
--   risk_assessment  = 7   (home readiness checklist)
--
-- DESTRUCTIVE: drops the existing tables and recreates + reseeds them.
-- Source: dpdpa.com (Adv. (Dr.) Prashant Mali), used with permission.
-- Run the whole script once in the Supabase SQL Editor.
-- =====================================================================

-- 0) Clean slate -------------------------------------------------------
drop table if exists public.quiz_questions  cascade;
drop table if exists public.exam_questions  cascade;
drop table if exists public.risk_assessment cascade;

-- 1) quiz_questions ----------------------------------------------------
create table public.quiz_questions (
  id          bigint generated always as identity primary key,
  question    text     not null,
  options     jsonb    not null,
  correct     smallint not null,
  explanation text     not null,
  difficulty  text,
  category    text,
  created_at  timestamptz not null default now()
);
alter table public.quiz_questions enable row level security;
create policy "Public read access" on public.quiz_questions
  for select to anon, authenticated using (true);

-- 2) exam_questions ----------------------------------------------------
create table public.exam_questions (
  id          bigint generated always as identity primary key,
  question    text     not null,
  options     jsonb    not null,
  correct     smallint not null,
  module      smallint not null,
  scenario    boolean  not null default false,
  difficulty  text,
  explanation text,
  created_at  timestamptz not null default now()
);
alter table public.exam_questions enable row level security;
create policy "Public read access" on public.exam_questions
  for select to anon, authenticated using (true);

-- 3) risk_assessment ---------------------------------------------------
create table public.risk_assessment (
  id         bigint generated always as identity primary key,
  prompt     text not null,
  sort_order int  not null,
  created_at timestamptz not null default now()
);
alter table public.risk_assessment enable row level security;
create policy "Public read access" on public.risk_assessment
  for select to anon, authenticated using (true);

-- Done. Verify:
--   select count(*) from public.quiz_questions;   -- 50
--   select count(*) from public.exam_questions;   -- 224
--   select count(*) from public.risk_assessment;  -- 7
