insert into public.quiz_questions (question, options, correct, explanation, difficulty, category) values
  ('What does DPDPA stand for?', '["Digital Personal Data Privacy Act","Digital Personal Data Protection Act","Data Protection and Digital Privacy Act","Digital Privacy Data Protection Act"]'::jsonb, 1, 'DPDPA stands for Digital Personal Data Protection Act, 2023. This is India''s primary legislation for data protection enacted to regulate the processing of digital personal data. (Reference: DPDPA 2023, Title)', 'basic', 'Fundamentals'),
  ('When did the Digital Personal Data Protection Act receive Presidential assent?', '["August 11, 2022","August 11, 2023","December 15, 2023","January 1, 2024"]'::jsonb, 1, 'The DPDPA received Presidential assent on August 11, 2023, marking a significant milestone in India''s data protection framework. (Reference: DPDPA 2023, Enactment Date)', 'basic', 'Fundamentals'),
  ('Who is a ''Data Fiduciary'' under DPDPA?', '["Any person whose data is being processed","Any person who processes personal data","Any person who alone or in conjunction with others determines the purpose and means of processing personal data","Only government entities processing data"]'::jsonb, 2, 'Section 2(i) defines Data Fiduciary as any person who alone or in conjunction with others determines the purpose and means of processing of personal data. This includes both public and private entities that control data processing activities. (Reference: Section 2(i), DPDPA 2023)', 'basic', 'Definitions'),
  ('What is a ''Data Principal'' according to DPDPA?', '["The head of the Data Protection Board","The Chief Technology Officer of a company","The individual to whom the personal data relates","The Data Protection Officer"]'::jsonb, 2, 'Section 2(j) defines Data Principal as the individual to whom the personal data relates. The Data Principal is the person whose data is being processed and who has rights under the Act. (Reference: Section 2(j), DPDPA 2023)', 'basic', 'Definitions'),
  ('How many sections does the DPDPA 2023 contain?', '["25 sections","44 sections","60 sections","100 sections"]'::jsonb, 1, 'The Digital Personal Data Protection Act, 2023 is a compact legislation containing 44 sections organized across multiple chapters covering various aspects of data protection. (Reference: DPDPA 2023, Structure)', 'basic', 'Fundamentals'),
  ('What is the territorial scope of DPDPA?', '["Only applies within India","Applies to processing within India and offering goods/services to Data Principals in India","Only applies to Indian citizens","Applies globally without restrictions"]'::jsonb, 1, 'Section 3 provides extraterritorial application: DPDPA applies to processing of digital personal data within India and also to processing outside India if it''s in connection with any activity related to offering goods or services to Data Principals within India. (Reference: Section 3, DPDPA 2023)', 'basic', 'Scope'),
  ('What is ''Personal Data'' under DPDPA?', '["Only biometric information","Data about legal entities","Data about an individual who is identifiable by or in relation to such data","Only financial information"]'::jsonb, 2, 'Section 2(t) defines Personal Data as data about an individual who is identifiable by or in relation to such data. This is a broad definition covering any data that can identify a natural person. (Reference: Section 2(t), DPDPA 2023)', 'basic', 'Definitions'),
  ('Who is the central authority responsible for enforcement of DPDPA?', '["Supreme Court of India","Ministry of Electronics and Information Technology","Data Protection Board of India","CERT-In"]'::jsonb, 2, 'Chapter VII establishes the Data Protection Board of India as the independent authority responsible for monitoring and enforcing compliance with the provisions of DPDPA. The Board has adjudicatory and regulatory powers. (Reference: Section 18, Chapter VII, DPDPA 2023)', 'basic', 'Enforcement'),
  ('What is meant by ''processing'' of personal data?', '["Only storing data","Only sharing data","A wholly or partly automated operation or set of operations performed on digital personal data","Only deleting data"]'::jsonb, 2, 'Section 2(u) defines Processing as a wholly or partly automated operation or set of operations performed on digital personal data, including collection, recording, organization, structuring, storage, adaptation, retrieval, use, alignment, disclosure, erasure, or destruction. (Reference: Section 2(u), DPDPA 2023)', 'basic', 'Definitions'),
  ('Can DPDPA apply to non-automated processing of personal data?', '["Yes, it applies to all personal data processing","No, it only applies to digital personal data","Yes, but only for government entities","It depends on the sector"]'::jsonb, 1, 'DPDPA specifically applies to ''digital personal data'' which means personal data in digitized form. The Act does not regulate manual or non-automated processing of data unless it''s part of a filing system. This is a key distinction from GDPR. (Reference: Section 2(h), Section 3, DPDPA 2023)', 'basic', 'Scope'),
  ('Which of the following is NOT a ground for processing personal data under DPDPA?', '["Consent of the Data Principal","For certain legitimate uses","Commercial interests of the Data Fiduciary","For compliance with any law"]'::jsonb, 2, 'Section 6 specifies lawful grounds for processing including consent, legitimate uses, and legal compliance. However, ''commercial interests'' alone is not a lawful ground. Processing must be based on consent or fall within specified legitimate purposes defined in Section 7. (Reference: Section 6, DPDPA 2023)', 'intermediate', 'Processing Grounds'),
  ('What are the essential characteristics of valid consent under DPDPA?', '["Free and specific","Free, specific, informed, unconditional and unambiguous","Written and notarized","Verbal or written"]'::jsonb, 1, 'Section 6(1) mandates that consent must be free, specific, informed, unconditional, and unambiguous with a clear affirmative action. This ensures Data Principals have genuine control. Bundled or coerced consent is invalid under this framework. (Reference: Section 6(1), DPDPA 2023)', 'intermediate', 'Consent'),
  ('Can a Data Principal withdraw consent once given?', '["No, consent is irrevocable","Yes, and it should be as easy as giving consent","Only with written application to Data Protection Board","Only if Data Fiduciary agrees"]'::jsonb, 1, 'Section 6(3) provides that withdrawal of consent shall be as easy as giving consent, ensuring Data Principals maintain continuous control over their data. However, withdrawal doesn''t affect lawfulness of processing done before withdrawal. (Reference: Section 6(3), DPDPA 2023)', 'intermediate', 'Consent'),
  ('Which right allows a Data Principal to correct inaccurate personal data?', '["Right to information","Right to correction and erasure","Right to data portability","Right to grievance redressal"]'::jsonb, 1, 'Section 12 provides Data Principals the right to correction of inaccurate or misleading personal data and completion of incomplete personal data, as well as erasure of personal data when retention is no longer necessary or consent is withdrawn. (Reference: Section 12, DPDPA 2023)', 'intermediate', 'Data Principal Rights'),
  ('What must a Data Fiduciary do when processing children''s data?', '["No special obligations","Obtain verifiable consent of parent or lawful guardian","Only process for educational purposes","Register with the Data Protection Board"]'::jsonb, 1, 'Section 9 mandates that Data Fiduciaries must obtain verifiable consent of parents or lawful guardians before processing children''s data. The government may specify age thresholds and exempt certain categories of Data Fiduciaries from this requirement. (Reference: Section 9, DPDPA 2023)', 'intermediate', 'Special Categories'),
  ('What is the maximum penalty for non-compliance with Data Protection Board directions?', '["₹50 crore","₹100 crore","₹200 crore","₹250 crore"]'::jsonb, 3, 'Section 33(1) prescribes that Data Fiduciaries failing to comply with Board directions may face penalties up to ₹250 crore. This represents the highest category of penalties under DPDPA, reflecting the seriousness of non-compliance with regulatory orders. (Reference: Section 33(1), DPDPA 2023)', 'intermediate', 'Penalties'),
  ('Who can file a complaint with the Data Protection Board?', '["Only lawyers","Only Data Principals affected","Any Data Principal or any person authorized by Data Principal","Only NGOs and civil society organizations"]'::jsonb, 2, 'Section 17 permits any Data Principal or any person authorized by the Data Principal to file a complaint with the Board regarding violation of provisions of the Act. This ensures accessibility to grievance mechanisms. (Reference: Section 17, DPDPA 2023)', 'intermediate', 'Grievance Redressal'),
  ('What is the purpose limitation principle under DPDPA?', '["Data can be used for any purpose","Personal data should be processed only for specified, clear, and lawful purposes","Data processing has time limitations","Only specific sectors can process data"]'::jsonb, 1, 'Section 8(2) embodies the purpose limitation principle requiring Data Fiduciaries to process personal data only for purposes that are clear and specified. Further processing must be compatible with the original purpose or require fresh consent. (Reference: Section 8(2), DPDPA 2023)', 'intermediate', 'Processing Principles'),
  ('What is a ''Data Processor'' under DPDPA?', '["Same as Data Fiduciary","Any person who processes personal data on behalf of a Data Fiduciary","The Data Protection Board","A hardware device that processes data"]'::jsonb, 1, 'Section 2(k) defines Data Processor as any person who processes personal data on behalf of a Data Fiduciary. Processors act on instructions from Fiduciaries and have their own set of obligations under Section 8. (Reference: Section 2(k), Section 8(6), DPDPA 2023)', 'intermediate', 'Definitions'),
  ('How long can a Data Fiduciary retain personal data?', '["Indefinitely","Maximum 5 years","Only for as long as necessary for the specified purpose or as required by law","Until Data Principal withdraws consent"]'::jsonb, 2, 'Section 8(5) requires that personal data shall not be retained beyond the period necessary to satisfy the purpose for which it is processed, unless required by law. This storage limitation principle prevents indefinite data hoarding. (Reference: Section 8(5), DPDPA 2023)', 'intermediate', 'Data Retention'),
  ('What is a ''Significant Data Fiduciary'' and who determines this classification?', '["Any Data Fiduciary processing more than 1 lakh data subjects","Data Fiduciaries designated by the Central Government based on specific factors","Only government departments","Data Fiduciaries who have faced penalties"]'::jsonb, 1, 'Section 10 empowers the Central Government to notify certain Data Fiduciaries as Significant Data Fiduciaries based on factors like volume and sensitivity of data, risk to rights of Data Principals, potential impact on sovereignty and integrity of India, among others. These entities face enhanced obligations. (Reference: Section 10, DPDPA 2023)', 'advanced', 'Significant Data Fiduciaries'),
  ('What additional obligations do Significant Data Fiduciaries have?', '["Only higher penalties","Must appoint a Data Protection Officer, conduct periodic audits, and conduct Data Protection Impact Assessments","Must relocate servers to India","Must obtain annual certification"]'::jsonb, 1, 'Section 10(3) mandates that Significant Data Fiduciaries must: (a) appoint a Data Protection Officer; (b) appoint an independent data auditor; (c) conduct periodic Data Protection Impact Assessments; and (d) undertake other measures as may be prescribed. These enhanced obligations reflect greater responsibility. (Reference: Section 10(3), DPDPA 2023)', 'advanced', 'Significant Data Fiduciaries'),
  ('Under what circumstances can personal data be processed without consent?', '["Never, consent is always mandatory","For specified legitimate uses including state functions, legal obligations, employment, medical emergency, etc.","Whenever commercially necessary","Only with court orders"]'::jsonb, 1, 'Section 7 lists legitimate uses where consent is not required, including: voluntary provision by Data Principal, functions of the State, legal rights/claims, employment purposes, medical emergency, disaster management, public health, research, and certain specified purposes. Each has specific conditions. (Reference: Section 7, DPDPA 2023)', 'advanced', 'Legitimate Uses'),
  ('What is the consequence if a Data Fiduciary fails to implement reasonable security safeguards?', '["Warning only","₹50 crore penalty","₹250 crore penalty","₹10,000 penalty"]'::jsonb, 2, 'Section 33(2) specifies penalties up to ₹250 crore for failure to implement reasonable security safeguards under Section 8(4). However, Section 33(2) itemizes specific violations with ₹50 crore penalties, while Section 33(3) provides for ₹200 crore penalties for breach of children''s data obligations. (Reference: Section 33(2), DPDPA 2023)', 'advanced', 'Penalties'),
  ('Can the Central Government exempt certain Data Fiduciaries from DPDPA provisions?', '["No, the Act applies universally without exemptions","Yes, in the interests of sovereignty, security, public order, or friendly relations with foreign states","Only with parliamentary approval","Only for temporary periods not exceeding 6 months"]'::jsonb, 1, 'Section 17 empowers the Central Government to exempt any instrumentality of the State from provisions of the Act in the interests of sovereignty and integrity of India, security of the State, friendly relations with foreign states, maintenance of public order, or preventing incitement to any cognizable offense. These exemptions are subject to procedural safeguards. (Reference: Section 17, DPDPA 2023)', 'advanced', 'Exemptions'),
  ('What is the time limit for Data Fiduciaries to respond to Data Principal rights requests?', '["7 days","As may be prescribed, considering volume and complexity","30 days","No time limit specified"]'::jsonb, 1, 'While the Act doesn''t specify exact timelines in the statute itself, Section 8(9) requires Data Fiduciaries to address grievances and respond to requests in such manner and within such period as may be prescribed by rules. The DPDP Rules 2025 specify detailed timelines. (Reference: Section 8(9), DPDPA 2023; DPDP Rules 2025)', 'advanced', 'Compliance'),
  ('What happens if there is a personal data breach?', '["No obligations on Data Fiduciary","Data Fiduciary must notify the Board and affected Data Principals as prescribed","Only notify if more than 10,000 users affected","Only criminal liability"]'::jsonb, 1, 'Section 8(7) mandates that in case of a personal data breach, the Data Fiduciary shall give the Board and each affected Data Principal intimation of such breach in such form and manner as may be prescribed. This ensures transparency and enables affected individuals to take protective measures. (Reference: Section 8(7), DPDPA 2023)', 'advanced', 'Data Breach'),
  ('Does DPDPA create a right to be forgotten?', '["Yes, explicitly mentioned","No such right exists","Indirectly through right to erasure when retention is no longer necessary","Only for minors"]'::jsonb, 2, 'Section 12 provides a right to correction and erasure. While not explicitly termed ''right to be forgotten'' like GDPR Article 17, the erasure right applies when retention is no longer necessary for the specified purpose or consent is withdrawn, achieving a similar outcome with Indian context. (Reference: Section 12, DPDPA 2023)', 'advanced', 'Data Principal Rights'),
  ('What is the composition of the Data Protection Board of India?', '["One Chairperson only","Chairperson and members as prescribed by Central Government","Chairperson and 10 members","Chairperson, State representatives, and industry members"]'::jsonb, 1, 'Section 19 establishes that the Board shall consist of a Chairperson and such number of members as the Central Government may prescribe. The qualification, appointment, tenure, and conditions of service are to be prescribed, ensuring appropriate expertise and independence. (Reference: Section 19, DPDPA 2023)', 'advanced', 'Data Protection Board'),
  ('Can decisions of the Data Protection Board be appealed?', '["No appeals allowed","Yes, to Supreme Court only","Yes, to Telecom Disputes Settlement and Appellate Tribunal (TDSAT)","Yes, to High Court"]'::jsonb, 2, 'Section 29 provides that any person aggrieved by a decision or order of the Board may file an appeal to the Telecom Disputes Settlement and Appellate Tribunal. This ensures judicial oversight while leveraging existing specialized tribunals familiar with digital economy issues. (Reference: Section 29, DPDPA 2023)', 'advanced', 'Appeals'),
  ('What is meant by ''verifiable consent'' for children''s data?', '["Any consent from the child","Consent that ensures reasonable verification of the identity and age of parent/guardian","Notarized consent","Consent via Aadhaar authentication"]'::jsonb, 1, 'Section 9 requires ''verifiable consent of parents or lawful guardian'' meaning the Data Fiduciary must implement reasonable methods to verify the identity and relationship of the person providing consent, ensuring genuine parental authorization before processing children''s data. (Reference: Section 9, DPDPA 2023)', 'intermediate', 'Special Categories'),
  ('Is there a data localization requirement under DPDPA?', '["Yes, all data must be stored in India","No restriction on data transfer","Government may restrict transfer to certain countries","Only financial data must be localized"]'::jsonb, 2, 'Section 16 empowers the Central Government to restrict transfer of personal data by a Data Fiduciary to certain countries or territories. Unlike earlier drafts, DPDPA doesn''t mandate blanket data localization but gives government power to restrict based on specific concerns. (Reference: Section 16, DPDPA 2023)', 'intermediate', 'Data Transfer'),
  ('What is the penalty for Data Principals providing false information?', '["No penalty on Data Principals","₹10,000 per default","₹1 lakh","Criminal prosecution"]'::jsonb, 1, 'Section 35 uniquely imposes obligations on Data Principals not to impersonate others, suppress material information, or register false complaints. Violation may result in penalty up to ₹10,000 per default, balancing rights with responsibilities. (Reference: Section 35, DPDPA 2023)', 'intermediate', 'Data Principal Duties'),
  ('Can a Data Fiduciary use personal data for targeted advertising without consent?', '["Yes, always allowed","No, explicit consent required for targeted advertising to children; general advertising may fall under legitimate use","Only if user doesn''t opt-out","Only for free services"]'::jsonb, 1, 'Section 9 specifically prohibits tracking or behavioral monitoring of children or targeted advertising directed at children. For adults, targeted advertising may require consent as it involves profiling, though this area awaits detailed regulatory guidance. (Reference: Section 9, DPDPA 2023)', 'advanced', 'Advertising & Marketing'),
  ('What is the notice requirement when collecting personal data?', '["No notice required","Notice must be given in clear and plain language","Legal notice format mandatory","Notice only if specifically requested"]'::jsonb, 1, 'Section 8(3) mandates that Data Fiduciaries must give Data Principals a notice containing prescribed particulars before or at the time of seeking consent or collecting data. The notice must be in clear and plain language, enabling informed decision-making. (Reference: Section 8(3), DPDPA 2023)', 'intermediate', 'Notice Requirements'),
  ('Which principle requires processing only the minimum data necessary?', '["Purpose Limitation","Data Minimization","Storage Limitation","Accuracy"]'::jsonb, 1, 'Though not explicitly stated as ''data minimization'' in a single section, this principle is embedded throughout DPDPA. Section 8 requires that processing be necessary for the specified purpose, implicitly requiring collection of only essential data. This aligns with global best practices. (Reference: Section 8, DPDPA 2023)', 'intermediate', 'Processing Principles'),
  ('What duty does a Data Processor have under DPDPA?', '["Same as Data Fiduciary","Process data only pursuant to contract and instructions of Data Fiduciary","No specific duties mentioned","Only data security duties"]'::jsonb, 1, 'Section 8(6) specifies that Data Processors may process personal data only pursuant to a valid contract with and on instructions of the Data Fiduciary. They cannot process data for their own purposes or beyond the scope of instructions received. (Reference: Section 8(6), DPDPA 2023)', 'advanced', 'Data Processor Obligations'),
  ('Can research institutions process personal data without consent?', '["Never without consent","Yes, for research, archiving or statistical purposes subject to safeguards","Only government research institutions","Only anonymized data"]'::jsonb, 1, 'Section 7(j) permits processing for research, archiving, or statistical purposes without consent, provided certain safeguards specified by government are followed. This balances research needs with privacy protection, following the K.S. Puttaswamy judgment''s emphasis on proportionality. (Reference: Section 7(j), DPDPA 2023)', 'advanced', 'Legitimate Uses'),
  ('What is the penalty for breach of confidentiality by Board members?', '["Dismissal from service","₹1 lakh","No specific penalty under DPPA for Board members","Imprisonment up to 2 years and fine"]'::jsonb, 2, 'Just that sections 8,9 and 10 places indirect responsibility on Board members and officers to maintain confidentiality, ensuring high standards of data protection at the regulatory level itself. (Reference: Sections 8, 9 and 10 DPDPA 2023)', 'advanced', 'Board Confidentiality'),
  ('When did the DPDP Rules, 2025 come into force?', '["November 14, 2025","November 13, 2025","December 15, 2024","Rules not yet notified"]'::jsonb, 1, 'The Digital Personal Data Protection Rules, 2025 were notified on November 13, 2025, providing the operational framework for implementing the DPDPA. These rules detail procedural aspects, forms, timelines, and technical requirements for compliance. (Reference: DPDP Rules 2025, Notification Date)', 'basic', 'Rules & Regulations'),
  ('What is the philosophical foundation of DPDPA rooted in?', '["Contract Theory","Right to Privacy as Fundamental Right (K.S. Puttaswamy judgment)","Property Rights","Commercial Law"]'::jsonb, 1, 'DPDPA is rooted in the landmark Justice K.S. Puttaswamy v. Union of India (2017) judgment which declared privacy as a fundamental right under Article 21 of the Constitution. The Act operationalizes this right in the digital context, balancing individual autonomy with legitimate state and commercial interests. (Reference: K.S. Puttaswamy v. Union of India (2017) 10 SCC 1; DPDPA 2023 Preamble)', 'intermediate', 'Constitutional Framework'),
  ('How does DPDPA balance innovation with privacy?', '["It doesn''t, privacy is absolute","Through exemptions for startups and legitimate use provisions","Innovation is not considered","Only through penalties"]'::jsonb, 1, 'DPDPA embodies proportionality by providing legitimate use exemptions (Section 7), permitting research (Section 7(j)), allowing government to exempt certain processing for innovation, and adopting lighter obligations compared to GDPR. This reflects the Puttaswamy judgment''s emphasis on balancing fundamental rights with other legitimate interests. (Reference: Section 7, DPDPA 2023; Puttaswamy judgment (proportionality test))', 'advanced', 'Policy Framework'),
  ('What is the significance of ''digital personal data'' limitation?', '["No significance","Excludes manual/paper records from Act''s scope, focusing on digital economy risks","Only applies to cloud data","Applies only to encrypted data"]'::jsonb, 1, 'By limiting scope to ''digital personal data'' (Section 2(h)), DPDPA acknowledges the unique risks of digital processing - scale, speed, profiling capabilities, and cross-border flows. This focused approach differs from GDPR and reflects India''s priority to regulate digital economy harms while not overburdening traditional paper-based operations. (Reference: Section 2(h), Section 3, DPDPA 2023)', 'advanced', 'Scope & Philosophy'),
  ('Which factor is NOT considered for designating a Significant Data Fiduciary?', '["Volume and sensitivity of personal data","Annual revenue of the organization","Risk to rights of Data Principals","Potential impact on sovereignty of India"]'::jsonb, 1, 'Section 10(1) lists factors including: (a) volume and sensitivity of data; (b) risk to rights of Data Principals; (c) potential impact on sovereignty and integrity of India; (d) risk to electoral democracy; (e) security of State; and (f) public order. Annual revenue is not a statutory criterion, though it may be indirectly relevant to volume. (Reference: Section 10(1), DPDPA 2023)', 'advanced', 'Significant Data Fiduciaries'),
  ('What is the role of a Data Protection Officer?', '["Marketing role","Represent Significant Data Fiduciary for compliance and interface with Board and Data Principals","Only technical role","Financial auditor"]'::jsonb, 1, 'Section 10(3)(a) mandates Significant Data Fiduciaries to appoint a Data Protection Officer (DPO) who serves as the point of contact with the Data Protection Board and Data Principals. The DPO ensures organizational compliance, conducts training, and represents the entity on data protection matters. (Reference: Section 10(3)(a), DPDPA 2023)', 'intermediate', 'Significant Data Fiduciaries'),
  ('Can personal data of deceased persons be processed under DPDPA?', '["Yes, same rules apply","No, Act doesn''t apply to deceased persons","Only with legal heir consent","Only government can process"]'::jsonb, 1, 'DPDPA defines Data Principal as an ''individual'' to whom the data relates. Since deceased persons are not ''individuals'' in the legal sense of having rights, the Act does not apply to data of deceased persons. However, processing such data may be regulated under other laws or ethical frameworks. (Reference: Section 2(j), DPDPA 2023)', 'advanced', 'Scope'),
  ('What is consent fatigue and how does DPDPA address it?', '["DPDPA doesn''t address consent fatigue","Through legitimate use provisions and implied consent for certain processing","By making all consent permanent","Through simplified consent forms only"]'::jsonb, 1, 'Consent fatigue occurs when users are overwhelmed with consent requests. DPDPA addresses this through Section 7''s legitimate use provisions, allowing processing without consent for specified purposes like employment, legal obligations, and voluntary provision by Data Principal, reducing unnecessary consent requests while maintaining protection. (Reference: Section 7, DPDPA 2023)', 'advanced', 'Practical Compliance'),
  ('Which constitutional article forms the basis of the right to privacy?', '["Article 19","Article 21","Article 14","Article 32"]'::jsonb, 1, 'The Supreme Court in K.S. Puttaswamy v. Union of India held that the right to privacy is a fundamental right protected under Article 21 (right to life and personal liberty) read with Article 19 (freedom of speech and expression) of the Constitution. DPDPA operationalizes this constitutional mandate. (Reference: Article 21, Constitution of India; Puttaswamy judgment)', 'intermediate', 'Constitutional Framework'),
  ('What test must government exemptions satisfy as per constitutional principles?', '["Rational nexus test","Proportionality test (legitimate aim, necessity, proportionality, procedural safeguards)","Reasonableness test only","No test required"]'::jsonb, 1, 'The Puttaswamy judgment established that any restriction on privacy must satisfy the proportionality test: (i) legitimate state aim, (ii) suitable/necessary measure, (iii) proportionate means, and (iv) procedural safeguards. Section 17 exemptions must satisfy these constitutional standards to withstand judicial scrutiny. (Reference: Puttaswamy judgment; Section 17, DPDPA 2023)', 'advanced', 'Constitutional Framework'),
  ('How does DPDPA differ from GDPR in enforcement approach?', '["No difference","DPDPA uses administrative penalties by Board; GDPR has both administrative fines and civil liability","DPDPA has criminal penalties only","DPDPA has no enforcement mechanism"]'::jsonb, 1, 'DPDPA establishes an administrative enforcement model through the Data Protection Board with prescribed penalties (Sections 33-34), while GDPR provides for administrative fines by supervisory authorities plus civil liability. DPDPA''s approach reflects India''s regulatory preference for specialized tribunals with sectoral expertise. (Reference: Sections 18, 33-34, DPDPA 2023; GDPR Articles 82-83)', 'advanced', 'Comparative Analysis');
insert into public.exam_questions (question, options, correct, module, scenario, difficulty) values
  ('What is the primary objective of the Digital Personal Data Protection Act, 2023?', '["To regulate all data processing in India","To balance the right to protection of personal data with the need to process such data","To prevent all cross-border data transfers","To establish a data localization mandate"]'::jsonb, 1, 1, false, 'basic'),
  ('Under DPDPA 2023, what is ''Personal Data''?', '["Only biometric and financial information","Data about a natural person who is identifiable by or in relation to such data","Any data stored in electronic format","Only data collected with consent"]'::jsonb, 1, 1, false, 'basic'),
  ('When did the DPDPA 2023 receive Presidential assent?', '["June 15, 2023","August 11, 2023","December 15, 2023","January 10, 2024"]'::jsonb, 1, 1, false, 'basic'),
  ('What is the territorial scope of DPDPA?', '["Applies only within India","Applies to processing in India and outside India if offering goods/services to Data Principals in India","Applies only to Indian companies","Applies only to government entities"]'::jsonb, 1, 1, false, 'basic'),
  ('Which constitutional judgment forms the foundation of the DPDPA, 2023?', '["Maneka Gandhi v. Union of India","K.S. Puttaswamy v. Union of India","ADM Jabalpur v. Shivkant Shukla","Shreya Singhal v. Union of India"]'::jsonb, 1, 1, false, 'basic'),
  ('Which category of data is explicitly excluded from the scope of the DPDPA?', '["Digitised personal data","Personal data processed by private companies","Anonymised data","Personal data processed by the State"]'::jsonb, 2, 1, false, 'basic'),
  ('Does the DPDPA apply to personal data processed for household purposes?', '["Yes, without exception","Yes, only if digital","No, personal or domestic purposes are exempt","Only if shared on social media"]'::jsonb, 2, 1, false, 'basic'),
  ('Which form of data triggers applicability of the DPDPA?', '["Only paper-based records","Only biometric databases","Digital personal data or data digitised subsequently","Only government-held data"]'::jsonb, 2, 1, false, 'basic'),
  ('Who is the primary rights-holder under the DPDPA?', '["Data Fiduciary","Data Processor","Data Principal","Data Protection Board"]'::jsonb, 2, 1, false, 'basic'),
  ('Does DPDPA protect data of companies and firms?', '["Yes, all entities","Yes, listed companies only","No, it applies only to natural persons","Only startups"]'::jsonb, 2, 1, false, 'basic'),
  ('Which of the following best describes the nature of DPDPA?', '["Criminal statute","Purely contractual framework","Rights-based data protection law","Cybercrime legislation"]'::jsonb, 2, 1, false, 'basic'),
  ('Is intent of the data fiduciary relevant for determining applicability of DPDPA?', '["Yes, intent is mandatory","Only in criminal cases","No, applicability depends on processing activity","Only for government entities"]'::jsonb, 2, 1, false, 'basic'),
  ('Which authority enforces compliance under the DPDPA?', '["CERT-In","MeitY","Data Protection Board of India","Supreme Court of India"]'::jsonb, 2, 1, false, 'basic'),
  ('Does DPDPA apply to non-digital data stored permanently in files?', '["Yes, always","Yes, if consent exists","No, unless digitised","Only for government departments"]'::jsonb, 2, 1, false, 'basic'),
  ('What is the legislative nature of penalties under DPDPA?', '["Criminal imprisonment","Civil penalties without compensation","Administrative monetary penalties","Contractual damages"]'::jsonb, 2, 1, false, 'basic'),
  ('Which principle best reflects the philosophy of DPDPA?', '["Absolute data localization","Consent at all costs","Balance between privacy and lawful processing","Government data ownership"]'::jsonb, 2, 1, false, 'basic'),
  ('Does the DPDPA override the IT Act, 2000?', '["Yes, fully repeals it","Only Section 43A","No, both operate concurrently","Only for private companies"]'::jsonb, 2, 1, false, 'basic'),
  ('What happens if offline data is later digitised?', '["DPDPA still does not apply","DPDPA applies prospectively","DPDPA applies once digitised","Only consent provisions apply"]'::jsonb, 2, 1, false, 'basic'),
  ('Which entity determines the purpose and means of processing?', '["Data Processor","Data Principal","Data Fiduciary","Data Auditor"]'::jsonb, 2, 1, false, 'basic'),
  ('Is harm mandatory to establish a DPDPA violation?', '["Yes, harm must be proven","Only financial harm","No, breach of obligation is sufficient","Only reputational harm"]'::jsonb, 2, 1, false, 'basic'),
  ('Which body appoints members of the Data Protection Board?', '["Supreme Court","Parliament","Central Government","Election Commission"]'::jsonb, 2, 1, false, 'basic'),
  ('Does DPDPA recognise data ownership?', '["Yes, Data Principal owns data","Yes, Government owns data","No, it recognises data rights, not ownership","Only companies own data"]'::jsonb, 2, 1, false, 'basic'),
  ('Which category of processing is exempt from DPDPA?', '["Commercial analytics","Personal data for domestic purposes","Employee monitoring","Marketing databases"]'::jsonb, 1, 1, false, 'basic'),
  ('Is DPDPA a technology-neutral law?', '["No, applies only to AI systems","No, applies only to cloud platforms","Yes, applies regardless of technology used","Only applies to mobile apps"]'::jsonb, 2, 1, false, 'basic'),
  ('Under DPDPA, who is a ''Data Fiduciary''?', '["The person whose data is being processed","Any person who determines the purpose and means of processing personal data","Only the Data Protection Board","Any IT company"]'::jsonb, 1, 1, false, 'basic'),
  ('What is a ''Data Processor'' under DPDPA?', '["The individual data subject","Any person who processes personal data on behalf of a Data Fiduciary","The Data Protection Board","Any government official"]'::jsonb, 1, 1, false, 'basic'),
  ('Which of the following is considered ''processing'' under DPDPA?', '["Only storage of data","Only deletion of data","Collection, storage, use, sharing, and deletion of data","Only sharing of data"]'::jsonb, 2, 1, false, 'basic'),
  ('[SCENARIO] A US-based e-commerce company has no physical presence in India but sells products to Indian customers through its website. Does DPDPA apply?', '["No, because the company has no offices in India","Yes, due to extraterritorial application under Section 3","Only if the company stores data in India","Only if annual sales exceed ₹100 crore"]'::jsonb, 1, 1, true, 'advanced'),
  ('What is the definition of ''Data Principal'' under DPDPA?', '["The person who controls the data","The natural person to whom the personal data relates","The Chief Data Officer","The Data Protection Board"]'::jsonb, 1, 1, false, 'basic'),
  ('Under DPDPA, can children''s personal data be processed?', '["No, never","Yes, with verifiable parental consent","Yes, without any restrictions","Only for educational purposes"]'::jsonb, 1, 1, false, 'basic'),
  ('What age is considered a ''child'' under DPDPA?', '["Under 16 years","Under 18 years","Under 21 years","As prescribed by the Central Government"]'::jsonb, 1, 1, false, 'basic'),
  ('Which body is responsible for enforcement of DPDPA?', '["Supreme Court of India","Ministry of Electronics and IT","Data Protection Board of India","Reserve Bank of India"]'::jsonb, 2, 1, false, 'basic'),
  ('[SCENARIO] A hospital in Mumbai treats patients from Nepal and Bangladesh. When processing their medical data, does DPDPA apply?', '["Yes, because processing occurs in India","No, because patients are not Indian citizens","Only for emergency treatments","Only if patients provide consent in writing"]'::jsonb, 0, 1, true, 'advanced'),
  ('What is the primary legal basis for processing personal data under DPDPA?', '["Legitimate interest only","Consent of the Data Principal","Government authorization","Payment of fees"]'::jsonb, 1, 1, false, 'basic'),
  ('Can personal data be processed for purposes other than the original purpose?', '["Yes, anytime without restrictions","Only with fresh consent or if covered under specified legitimate uses","Never allowed under any circumstances","Only with Data Protection Board approval"]'::jsonb, 1, 1, false, 'basic'),
  ('Under Section 7, which of these is a ''specified purpose'' for processing without consent?', '["Marketing purposes","Functions of the State","Third-party advertising","Employee monitoring"]'::jsonb, 1, 1, false, 'basic'),
  ('What does ''anonymization'' mean under DPDPA?', '["Encrypting personal data","Irreversible process of transforming data such that a Data Principal cannot be identified","Temporarily hiding identifiers","Storing data in a secure location"]'::jsonb, 1, 1, false, 'basic'),
  ('Is anonymized data covered under DPDPA?', '["Yes, fully regulated","No, because Data Principals cannot be identified","Only if re-identification is possible","Only for commercial purposes"]'::jsonb, 1, 1, false, 'basic'),
  ('[SCENARIO] An Indian fintech startup uses AWS (US-based) to store customer financial data. The fintech is the Data Fiduciary. What is AWS?', '["Also a Data Fiduciary","A Data Processor","A Data Principal","Not covered under DPDPA"]'::jsonb, 1, 1, true, 'advanced'),
  ('How many sections are there in the DPDPA 2023?', '["33 sections","44 sections","55 sections","66 sections"]'::jsonb, 1, 1, false, 'basic'),
  ('When were the DPDP Rules 2025 notified?', '["January 3, 2025","November 13, 2025","December 1, 2024","February 1, 2025"]'::jsonb, 1, 1, false, 'basic'),
  ('Which of the following is NOT a right of Data Principals under DPDPA?', '["Right to correction","Right to erasure","Right to data portability","Right to nominate"]'::jsonb, 2, 2, false, 'basic'),
  ('When must a Data Fiduciary provide a notice to Data Principals?', '["Only when requested by the Data Principal","Before or at the time of asking for consent","Within 30 days of data collection","Only if processing sensitive personal data"]'::jsonb, 1, 2, false, 'basic'),
  ('What must be included in the notice to Data Principals under Section 5?', '["Only the Data Fiduciary''s name","Personal data being collected, purpose, manner of exercising rights, and grievance redressal","Only the purpose of processing","Only contact details"]'::jsonb, 1, 2, false, 'basic'),
  ('Under Section 6, valid consent must be which of the following?', '["Implied, general, and permanent","Free, specific, informed, unambiguous, and involve clear affirmative action","Written, notarized, and witnessed","Verbal and recorded"]'::jsonb, 1, 2, false, 'basic'),
  ('[SCENARIO] An e-commerce app has a pre-ticked checkbox that says ''I agree to share my data with partners for marketing.'' Is this valid consent?', '["Yes, if users can untick it","No, consent must involve clear affirmative action (user must actively tick)","Yes, if mentioned in terms & conditions","Only valid for existing customers"]'::jsonb, 1, 2, true, 'advanced'),
  ('Can consent be withdrawn under DPDPA?', '["No, consent is permanent","Yes, as easily as it was given","Only with Data Protection Board approval","Only after 30 days"]'::jsonb, 1, 2, false, 'basic'),
  ('What is the Right to Correction under Section 12?', '["Right to sue for damages","Right to correct inaccurate or misleading personal data","Right to modify consent","Right to delete the Data Fiduciary''s records"]'::jsonb, 1, 2, false, 'basic'),
  ('What is the Right to Erasure under Section 10?', '["Right to erase the Data Fiduciary''s servers","Right to require cessation of data processing and deletion when consent is withdrawn or purpose is fulfilled","Right to delete other people''s data","Right to erase public records"]'::jsonb, 1, 2, false, 'basic'),
  ('[SCENARIO] A user withdraws consent for a shopping app to use their data for recommendations. The app says it will take 90 days to stop processing. Is this compliant?', '["Yes, 90 days is reasonable","No, processing must cease promptly unless another legal basis exists","Yes, if mentioned in privacy policy","Only if the user agrees to the delay"]'::jsonb, 1, 2, true, 'advanced'),
  ('What is the Right to Grievance Redressal under Section 13?', '["Right to file criminal complaints","Right to seek remedies for failure to comply with DPDPA provisions","Right to compensation from the government","Right to data portability"]'::jsonb, 1, 2, false, 'basic'),
  ('What is the Right to Nominate under Section 14?', '["Right to nominate a Data Fiduciary","Right to nominate another person to exercise rights in the event of death or incapacity","Right to nominate a lawyer","Right to nominate data for deletion"]'::jsonb, 1, 2, false, 'basic'),
  ('Under Section 8, what are the obligations of a Data Fiduciary?', '["Only to store data securely","Process lawfully, ensure accuracy, implement security safeguards, delete data upon purpose completion","Only to obtain consent","Only to respond to requests"]'::jsonb, 1, 2, false, 'basic'),
  ('What is the purpose limitation principle under Section 4?', '["Data can be used for any purpose","Personal data shall be processed only for lawful purposes for which consent was given","Purpose can be changed without notice","Purpose is decided by the Data Protection Board"]'::jsonb, 1, 2, false, 'basic'),
  ('[SCENARIO] A telecom company collects customer data for billing purposes but starts using it for targeted advertising without fresh consent. Is this allowed?', '["Yes, if disclosed in privacy policy","No, violates purpose limitation - fresh consent is required","Yes, if customers are notified","Only for existing customers"]'::jsonb, 1, 2, true, 'advanced'),
  ('Under Section 8(3), what is the accuracy obligation?', '["Data must be 100% perfect","Data Fiduciary must ensure completeness, accuracy, and consistency of personal data","Only financial data must be accurate","Accuracy is optional"]'::jsonb, 1, 2, false, 'basic'),
  ('What is data minimization under Section 4?', '["Collecting as much data as possible","Collecting only data necessary for the specified purpose","Minimizing storage costs","Collecting data from minimal sources"]'::jsonb, 1, 2, false, 'basic'),
  ('Under Section 8(7), when must personal data be deleted?', '["Never, data can be kept indefinitely","When it is no longer necessary for the purpose or consent is withdrawn","After 10 years","Only when requested by Data Principal"]'::jsonb, 1, 2, false, 'basic'),
  ('[SCENARIO] A job portal keeps candidate data for 5 years after the hiring process ends ''for future opportunities.'' Is this compliant without fresh consent?', '["Yes, it''s good practice","No, violates data retention principles - must delete or obtain fresh consent for new purpose","Yes, if mentioned in privacy policy","Only for successful candidates"]'::jsonb, 1, 2, true, 'advanced'),
  ('What are ''reasonable security safeguards'' under Section 8(5)?', '["Only antivirus software","Measures to prevent data breaches, including technical, operational, and organizational measures","Only passwords","Only firewalls"]'::jsonb, 1, 2, false, 'basic'),
  ('Under Section 8(6), when must a Data Fiduciary notify a breach to the Board?', '["Within 72 hours","As soon as reasonably possible after becoming aware","Within 30 days","Never, only Data Principals need notification"]'::jsonb, 0, 2, false, 'basic'),
  ('[SCENARIO] A mobile app uses pre-ticked boxes for accepting its privacy policy. Under DPDPA, is this valid consent?', '["No, consent must be by clear affirmative action","Yes, if disclosed in the policy","Yes, if users can later opt out","Only for government apps"]'::jsonb, 0, 2, true, 'advanced'),
  ('[SCENARIO] An e-commerce platform bundles consent for marketing emails with account creation. Is this compliant?', '["Yes, bundled consent is permitted","No, consent must be specific and granular","Only if emails are infrequent","Yes, for registered users"]'::jsonb, 1, 2, true, 'advanced'),
  ('[SCENARIO] A hospital processes patient data during an emergency without consent. Is this lawful under DPDPA?', '["Only if later consent is taken","Only for government hospitals","Yes, under legitimate use for medical emergency","No, consent is mandatory"]'::jsonb, 2, 2, true, 'advanced'),
  ('[SCENARIO] An employer processes employee attendance data without explicit consent. Is this allowed?', '["Only if employees agree in writing","Yes, under legitimate use for employment purposes","No, consent is mandatory","Only for public sector employers"]'::jsonb, 1, 2, true, 'advanced'),
  ('[SCENARIO] A fintech app continues processing personal data after consent has been withdrawn. Is this compliant?', '["Yes, for analytics purposes","Only if anonymised","No, processing must stop after withdrawal","Yes, if data was already collected"]'::jsonb, 2, 2, true, 'advanced'),
  ('[SCENARIO] A data fiduciary seeks consent using vague language like ''for business purposes''. Is this valid?', '["Yes, broad purposes are allowed","Only for startups","No, consent must be informed and specific","Yes, if explained elsewhere"]'::jsonb, 2, 2, true, 'advanced'),
  ('[SCENARIO] A government department processes citizen data for subsidy distribution without consent. Is this lawful?', '["Yes, as a State function under legitimate use","Only with parliamentary approval","No, consent is mandatory","Only if data is encrypted"]'::jsonb, 0, 2, true, 'advanced'),
  ('[SCENARIO] A company relies on consent obtained before DPDPA enforcement without updating its notice. Is this valid?', '["Yes, old consent continues indefinitely","Only if users are informed orally","No, consent must meet DPDPA standards","Only for one year"]'::jsonb, 2, 2, true, 'advanced'),
  ('[SCENARIO] A social media platform processes data of children without parental consent. Is this permitted?', '["Only above age 13","Yes, if the child agreed","Only for educational content","No, verifiable parental consent is required"]'::jsonb, 3, 2, true, 'advanced'),
  ('[SCENARIO] A telecom company processes call data records to comply with a court order. Is consent required?', '["Only if data is sensitive","Yes, consent is mandatory","Only with DPB approval","No, processing is permitted for legal obligation"]'::jsonb, 3, 2, true, 'advanced'),
  ('[SCENARIO] A user clicks ''Agree'' without reading the notice. Is consent still valid?', '["Yes, if notice was accessible","No, reading is mandatory","Only if highlighted","Only for non-sensitive data"]'::jsonb, 0, 2, true, 'advanced'),
  ('[SCENARIO] A company collects personal data for one purpose and later uses it for another without consent. Is this lawful?', '["Yes, for internal use","No, fresh consent is required","Yes, if related purpose","Only if anonymised"]'::jsonb, 1, 2, true, 'advanced'),
  ('[SCENARIO] A food delivery app processes address data after order completion for analytics. Is this allowed?', '["Only if within stated purpose or consent","Never allowed","Yes, always","Only with DPB approval"]'::jsonb, 0, 2, true, 'advanced'),
  ('[SCENARIO] A data fiduciary refuses service unless consent for marketing is given. Is this valid consent?', '["Yes, service condition is allowed","Only for premium services","No, consent must be freely given","Only if disclosed"]'::jsonb, 2, 2, true, 'advanced'),
  ('[SCENARIO] A bank processes KYC data to meet RBI requirements without consent. Is this lawful?', '["Only with customer notice","Yes, under legal obligation","No, consent is mandatory","Only for public banks"]'::jsonb, 1, 2, true, 'advanced'),
  ('[SCENARIO] A data fiduciary fails to provide consent withdrawal mechanism. Is this compliant?', '["Yes, if consent was once given","Yes, if stated in policy","Only for small entities","No, withdrawal must be as easy as giving consent"]'::jsonb, 3, 2, true, 'advanced'),
  ('[SCENARIO] A logistics company processes delivery data after contract completion for dispute resolution. Is this permitted?', '["Yes, under legitimate use","Only with fresh consent","No, consent expired","Only for government contracts"]'::jsonb, 0, 2, true, 'advanced'),
  ('[SCENARIO] A user gives consent under pressure to avoid account suspension. Is consent valid?', '["Yes, user agreed","No, consent must be free of coercion","Only if approved by DPB","Yes, if documented"]'::jsonb, 1, 2, true, 'advanced'),
  ('[SCENARIO] A company processes personal data for fraud prevention without consent. Is this lawful?', '["Yes, under legitimate use","Only if anonymised","No, consent mandatory","Only for banks"]'::jsonb, 0, 2, true, 'advanced'),
  ('[SCENARIO] A startup collects consent via long unreadable legal text. Is this compliant?', '["Yes, length does not matter","Only if lawyer-drafted","Only for paid users","No, consent must be informed and clear"]'::jsonb, 3, 2, true, 'advanced'),
  ('When must Data Principals be notified about a breach under Section 8(6)?', '["Always, in all cases","Only if the breach is likely to cause harm to the Data Principal","Never, only the Board needs notification","Only for financial data breaches"]'::jsonb, 0, 2, false, 'basic'),
  ('What threshold makes a Data Fiduciary a ''Significant Data Fiduciary'' (SDF)?', '["Processing data of 10,000 individuals","Annual revenue exceeding ₹500 crore","As notified by the Central Government based on prescribed parameters","Processing any sensitive personal data"]'::jsonb, 2, 3, false, 'intermediate'),
  ('What is the primary responsibility of a Data Protection Officer (DPO)?', '["To manage IT infrastructure","To represent the Data Fiduciary before the Data Protection Board and ensure DPDPA compliance","To audit all third-party vendors","To approve all data processing activities"]'::jsonb, 1, 3, false, 'intermediate'),
  ('Under Rule 13, which entities MUST appoint a Data Protection Officer (DPO)?', '["All Data Fiduciaries","Only Significant Data Fiduciaries","Only government entities","Only companies with revenue > ₹100 crore"]'::jsonb, 1, 3, false, 'intermediate'),
  ('What are the additional obligations for Significant Data Fiduciaries under Section 9?', '["Pay higher fees only","Appoint DPO, conduct DPIA, conduct periodic audits, and other measures as prescribed","None, same as regular Data Fiduciaries","Only conduct audits"]'::jsonb, 1, 3, false, 'intermediate'),
  ('[SCENARIO] A social media platform with 50 million Indian users has been notified as an SDF. What new obligations does it have?', '["No additional obligations","Must appoint DPO, conduct DPIA, periodic audits, maintain processing records","Only pay higher penalties","Only faster breach notification"]'::jsonb, 1, 3, true, 'advanced'),
  ('What is a Data Protection Impact Assessment (DPIA)?', '["Financial impact analysis","Assessment of potential risks to rights of Data Principals from processing activities","Assessment of IT infrastructure","Market research"]'::jsonb, 1, 3, false, 'intermediate'),
  ('Under Rule 13, when must an SDF conduct a DPIA?', '["Never required","Before undertaking processing likely to involve significant risk to Data Principals","After a breach occurs","Every 5 years"]'::jsonb, 1, 3, false, 'intermediate'),
  ('What is the purpose of periodic audits for SDFs?', '["Financial compliance only","To assess compliance with DPDPA provisions and identify vulnerabilities","Tax purposes","Marketing assessment"]'::jsonb, 1, 3, false, 'intermediate'),
  ('[SCENARIO] An e-commerce company designated as SDF wants to launch a new AI-powered facial recognition payment system. What must it do first?', '["Launch immediately if technically ready","Conduct a Data Protection Impact Assessment (DPIA) to assess risks","Only obtain consent from users","Pay a fee to the Data Protection Board"]'::jsonb, 1, 3, true, 'advanced'),
  ('[SCENARIO] A user asks a company whether their personal data is being processed and requests a summary. Which right is being exercised?', '["Right to erasure","Right to grievance redressal","Right to access information","Right to correction"]'::jsonb, 2, 3, true, 'advanced'),
  ('[SCENARIO] A Data Principal requests correction of an incorrect address, but the company ignores the request. Which right is violated?', '["Right to nomination","Right to access","Right to correction and erasure","Right to consent withdrawal"]'::jsonb, 2, 3, true, 'advanced'),
  ('[SCENARIO] A user withdraws consent but the data fiduciary retains the data without lawful basis. Which right applies?', '["Right to erasure","Right to information","Right to grievance redressal","Right to correction"]'::jsonb, 0, 3, true, 'advanced'),
  ('[SCENARIO] A company provides incomplete information in response to an access request. Which right is impacted?', '["Right to grievance redressal","Right to access information","Right to nomination","Right to correction"]'::jsonb, 1, 3, true, 'advanced'),
  ('[SCENARIO] A Data Principal nominates their spouse to exercise rights after death. Which right is this?', '["Right to access","Right to correction","Right to nomination","Right to erasure"]'::jsonb, 2, 3, true, 'advanced'),
  ('[SCENARIO] A company refuses to delete personal data even after consent withdrawal and purpose completion. Which right is violated?', '["Right to erasure","Right to access","Right to nomination","Right to grievance redressal"]'::jsonb, 0, 3, true, 'advanced'),
  ('[SCENARIO] A Data Principal files a complaint but the company does not respond within reasonable time. Which right applies?', '["Right to information","Right to grievance redressal","Right to erasure","Right to correction"]'::jsonb, 1, 3, true, 'advanced'),
  ('[SCENARIO] A platform refuses to correct inaccurate personal data citing internal policy. Which right is breached?', '["Right to access","Right to grievance redressal","Right to correction","Right to nomination"]'::jsonb, 2, 3, true, 'advanced'),
  ('[SCENARIO] A user requests information about third parties with whom their data is shared. Which right applies?', '["Right to erasure","Right to access information","Right to nomination","Right to correction"]'::jsonb, 1, 3, true, 'advanced'),
  ('[SCENARIO] A Data Principal nominates a legal heir using an online portal. Is this valid under DPDPA?', '["No, nomination must be physical","Only for government services","Yes, digital nomination is permitted","Only after DPB approval"]'::jsonb, 2, 3, true, 'advanced'),
  ('[SCENARIO] A user seeks deletion of data that is still required under law. Can the fiduciary refuse?', '["Yes, legal obligation overrides erasure","No, erasure is absolute","Only with DPB approval","Only for government data"]'::jsonb, 0, 3, true, 'advanced'),
  ('[SCENARIO] A company demands a fee for correcting inaccurate personal data. Is this compliant?', '["Yes, administrative fees are allowed","Only for repeated requests","No, correction must be free of charge","Only for private companies"]'::jsonb, 2, 3, true, 'advanced'),
  ('[SCENARIO] A Data Principal requests data access in an unreadable format. Is the fiduciary compliant?', '["Yes, format does not matter","Only if data is complete","No, information must be understandable","Only for technical users"]'::jsonb, 2, 3, true, 'advanced'),
  ('[SCENARIO] A platform delays responding to a rights request indefinitely. Which remedy is available?', '["Direct criminal complaint","Approach Data Protection Board after grievance","Immediate civil suit","No remedy exists"]'::jsonb, 1, 3, true, 'advanced'),
  ('[SCENARIO] A user seeks erasure, but data has been anonymised. Is erasure still required?', '["Yes, anonymised data must be erased","No, anonymised data is outside DPDPA scope","Only for sensitive data","Only with consent"]'::jsonb, 1, 3, true, 'advanced'),
  ('[SCENARIO] A company denies access request claiming trade secrets. Is blanket denial allowed?', '["Yes, trade secrets override rights","Only with court order","No, limited disclosure must still be given","Only for startups"]'::jsonb, 2, 3, true, 'advanced'),
  ('[SCENARIO] A Data Principal submits a correction request with supporting documents. What must the fiduciary do?', '["Ignore unless court ordered","Verify and update data","Delete entire record","Forward to DPB"]'::jsonb, 1, 3, true, 'advanced'),
  ('[SCENARIO] A company requires Aadhaar to process a grievance request. Is this lawful?', '["Yes, for identity verification","Only with government approval","No, excessive data collection violates proportionality","Only for financial services"]'::jsonb, 2, 3, true, 'advanced'),
  ('[SCENARIO] A deceased user’s nominee requests account access. Which provision enables this?', '["Right to access","Right to nomination","Right to erasure","Right to correction"]'::jsonb, 1, 3, true, 'advanced'),
  ('[SCENARIO] A company auto-closes grievance tickets without resolution. Which right is affected?', '["Right to grievance redressal","Right to correction","Right to nomination","Right to erasure"]'::jsonb, 0, 3, true, 'advanced'),
  ('What is ''privacy by design'' under DPDPA?', '["Designing beautiful privacy policies","Integrating privacy considerations into the design of systems, processes, and products from the outset","Designing secure buildings","Graphic design for privacy notices"]'::jsonb, 1, 3, false, 'intermediate'),
  ('Under Section 16, what is required when processing personal data outside India?', '["Completely prohibited","Allowed to prescribed countries/territories with adequate data protection measures","Requires payment of fees","Requires individual permission for each transfer"]'::jsonb, 1, 3, false, 'intermediate'),
  ('What are ''Standard Contractual Clauses'' (SCCs) in the context of data transfers?', '["Marketing contracts","Pre-approved contractual terms to ensure adequate protection for cross-border transfers","Employment contracts","Vendor payment terms"]'::jsonb, 1, 3, false, 'intermediate'),
  ('[SCENARIO] An Indian bank wants to use a US-based cloud provider for storing customer data. What safeguards are needed?', '["None, cloud providers are automatically compliant","Data Processing Agreement ensuring DPDPA compliance, security measures, and proper transfer mechanisms","Only encryption","Only inform customers"]'::jsonb, 1, 3, true, 'advanced'),
  ('What is a ''Data Processing Agreement'' (DPA)?', '["Agreement between two Data Principals","Contract between Data Fiduciary and Data Processor defining terms of processing","Agreement with the Data Protection Board","Marketing agreement"]'::jsonb, 1, 3, false, 'intermediate'),
  ('What are the minimum elements required in a Data Processing Agreement?', '["Only payment terms","Scope of processing, processor obligations, data security, return/deletion provisions, sub-processor terms","Only confidentiality clause","Only termination clause"]'::jsonb, 1, 3, false, 'intermediate'),
  ('Under Section 8(1), who is accountable for the Data Processor''s compliance?', '["The Data Processor alone","The Data Fiduciary remains accountable","The Data Protection Board","No one is accountable"]'::jsonb, 1, 3, false, 'intermediate'),
  ('What is a ''Record of Processing Activities'' (RoPA)?', '["Financial records","Documentation of all processing activities including purposes, data categories, recipients, and retention","Employee attendance records","Marketing campaign records"]'::jsonb, 1, 3, false, 'intermediate'),
  ('[SCENARIO] During an audit, the Data Protection Board asks an SDF to produce its Record of Processing Activities (RoPA). The SDF doesn''t have one. What is the consequence?', '["Warning only for first offense","Penalty up to ₹250 crore for non-compliance with Section 10 obligations","No consequence","1-year grace period given"]'::jsonb, 1, 3, true, 'advanced'),
  ('What is the role of the Consent Manager under DPDPA?', '["Manages employee attendance","Helps Data Principals give, manage, review, and withdraw consent through interoperable platforms","Manages financial consents only","Government official"]'::jsonb, 1, 3, false, 'intermediate'),
  ('Who can register as a Consent Manager under DPDPA?', '["Any individual","Entities registered with the Data Protection Board meeting prescribed requirements","Only government entities","Only banks"]'::jsonb, 1, 3, false, 'intermediate'),
  ('What is the difference between a Data Fiduciary and a Consent Manager?', '["No difference, same role","Data Fiduciary processes data; Consent Manager facilitates consent management for Data Principals","Consent Manager is always a government entity","Data Fiduciary only stores data"]'::jsonb, 1, 3, false, 'intermediate'),
  ('What is the maximum penalty that the Data Protection Board can impose on a Data Fiduciary for non-compliance?', '["₹100 crore","₹250 crore","₹500 crore","As determined by the Board based on severity"]'::jsonb, 1, 4, false, 'intermediate'),
  ('Within what timeframe must a Data Fiduciary notify a personal data breach to the Board?', '["Immediately upon discovery","Within 72 hours","As soon as reasonably possible","Within 7 days"]'::jsonb, 1, 4, false, 'intermediate'),
  ('Under which section can penalties be imposed by the Data Protection Board?', '["Section 29","Section 33","Section 40","Section 50"]'::jsonb, 1, 4, false, 'intermediate'),
  ('What factors does the Data Protection Board consider when determining penalty amounts?', '["Only the company''s revenue","Nature, gravity, and duration of breach; type and nature of personal data; repetitive nature; actions taken to mitigate harm","Only the number of users affected","Random determination"]'::jsonb, 1, 4, false, 'intermediate'),
  ('[SCENARIO] A fintech startup suffers a data breach affecting 10,000 customers but notifies the Board within 2 hours and Data Principals within 24 hours. All affected were given 1 year of credit monitoring. How might this affect the penalty?', '["Maximum penalty automatically applied","Prompt notification and mitigation efforts are likely to reduce the penalty significantly","No penalty since notification was fast","Penalty doubled for having a breach"]'::jsonb, 1, 4, true, 'advanced'),
  ('Can the Data Protection Board issue directions to Data Fiduciaries?', '["No, only penalties","Yes, can issue directions to ensure compliance and protect Data Principal rights","Only to government entities","Only after court approval"]'::jsonb, 1, 4, false, 'intermediate'),
  ('What is the appeal mechanism under DPDPA?', '["No appeals allowed","Appeals to Telecom Disputes Settlement and Appellate Tribunal (TDSAT)","Appeals to Supreme Court directly","Appeals to Ministry of IT"]'::jsonb, 1, 4, false, 'intermediate'),
  ('Within what time period can an appeal be filed against a Data Protection Board order?', '["30 days","60 days","90 days","6 months"]'::jsonb, 1, 4, false, 'intermediate'),
  ('[SCENARIO] A Data Fiduciary is penalized ₹50 crore by the Board. The company believes the penalty is excessive. What is its recourse?', '["Must pay, no recourse","File appeal to TDSAT within 60 days","File review petition with the Board","Approach the Prime Minister''s Office"]'::jsonb, 1, 4, true, 'advanced'),
  ('What is the role of the Data Protection Board of India?', '["Only collecting penalties","Enforcement, adjudication of complaints, imposing penalties, issuing directions, and protecting Data Principal rights","Only policy making","Only conducting awareness programs"]'::jsonb, 1, 4, false, 'intermediate'),
  ('How is the Data Protection Board constituted?', '["Single member","Chairperson and members (whole-time and part-time) appointed by Central Government","Elected by Data Fiduciaries","Permanent bureaucrats"]'::jsonb, 1, 4, false, 'intermediate'),
  ('Can Data Principals file complaints directly with the Data Protection Board?', '["No, must go through courts only","Yes, Data Principals can file complaints regarding violations of their rights","Only through Consent Managers","Only if damages exceed ₹1 lakh"]'::jsonb, 1, 4, false, 'intermediate'),
  ('[SCENARIO] A user''s request for data erasure is ignored by an e-commerce platform for 90 days despite multiple follow-ups. What can the user do?', '["Nothing, must wait indefinitely","File a complaint with the Data Protection Board for violation of Right to Erasure","File criminal case directly","Approach consumer court only"]'::jsonb, 1, 4, true, 'advanced'),
  ('What is the penalty for non-compliance with Board directions?', '["No specific penalty","Up to ₹200 crore","Only warning","₹10 lakh"]'::jsonb, 1, 4, false, 'intermediate'),
  ('[SCENARIO] A company collects personal data without publishing a privacy notice. Which obligation under DPDPA is violated?', '["Duty to ensure data accuracy","Duty to provide notice","Duty to minimise data","Duty to appoint DPO"]'::jsonb, 1, 4, true, 'advanced'),
  ('[SCENARIO] A data fiduciary stores outdated customer information leading to incorrect service delivery. Which obligation is breached?', '["Data minimisation","Consent obligation","Data accuracy obligation","Grievance redressal"]'::jsonb, 2, 4, true, 'advanced'),
  ('[SCENARIO] A startup collects excessive personal data unrelated to its service. Which principle is violated?', '["Data minimisation","Purpose limitation","Consent withdrawal","Security safeguard"]'::jsonb, 0, 4, true, 'advanced'),
  ('[SCENARIO] A data fiduciary fails to implement reasonable security safeguards and suffers a breach. Which obligation applies?', '["Notice obligation","Security safeguard obligation","Consent obligation","Nomination obligation"]'::jsonb, 1, 4, true, 'advanced'),
  ('[SCENARIO] A company does not delete personal data even after the purpose is fulfilled. Which duty is violated?', '["Duty to erase personal data","Duty to appoint DPO","Duty to notify breach","Duty to obtain consent"]'::jsonb, 0, 4, true, 'advanced'),
  ('[SCENARIO] A Significant Data Fiduciary fails to appoint a Data Protection Officer. Is this compliant?', '["Yes, DPO is optional","Only required for government entities","No, appointment of DPO is mandatory","Only for foreign companies"]'::jsonb, 2, 4, true, 'advanced'),
  ('[SCENARIO] A data processor uses personal data for its own analytics without permission. Which rule is violated?', '["Processor limitation obligation","Consent obligation","Breach notification rule","Nomination rule"]'::jsonb, 0, 4, true, 'advanced'),
  ('[SCENARIO] A fiduciary outsources processing but fails to ensure contractual safeguards. What is the consequence?', '["Processor bears full liability","No consequence","Fiduciary remains responsible","Only DPB is responsible"]'::jsonb, 2, 4, true, 'advanced'),
  ('[SCENARIO] A company does not publish grievance redressal contact details. Which obligation is breached?', '["Security obligation","Grievance redressal obligation","Consent obligation","Data accuracy obligation"]'::jsonb, 1, 4, true, 'advanced'),
  ('[SCENARIO] A fiduciary continues processing data despite unresolved grievance. Is this allowed?', '["Yes, grievances do not affect processing","Only for public interest","No, fiduciary must address grievances promptly","Only for large companies"]'::jsonb, 2, 4, true, 'advanced'),
  ('[SCENARIO] A company does not conduct Data Protection Impact Assessment despite high-risk processing. Is this compliant?', '["Yes, DPIA is optional","Only required outside India","No, DPIA is mandatory for significant fiduciaries","Only after breach"]'::jsonb, 2, 4, true, 'advanced'),
  ('[SCENARIO] A fiduciary delays breach notification to affected users. Which obligation is violated?', '["Breach notification obligation","Data minimisation","Consent requirement","Nomination obligation"]'::jsonb, 0, 4, true, 'advanced'),
  ('[SCENARIO] A data fiduciary uses personal data beyond the stated purpose. Which duty is breached?', '["Purpose limitation obligation","Security safeguard","Nomination duty","Grievance handling"]'::jsonb, 0, 4, true, 'advanced'),
  ('[SCENARIO] A Significant Data Fiduciary does not appoint an independent auditor. Is this compliant?', '["Yes, audits are voluntary","Only required for banks","No, periodic audits are mandatory","Only after breach"]'::jsonb, 2, 4, true, 'advanced'),
  ('[SCENARIO] A fiduciary collects data lawfully but stores it indefinitely. Which principle is violated?', '["Storage limitation","Consent obligation","Data accuracy","Security safeguard"]'::jsonb, 0, 4, true, 'advanced'),
  ('[SCENARIO] A data processor sub-contracts processing without informing the fiduciary. Is this allowed?', '["Yes, processors are independent","Only for cloud providers","No, fiduciary authorisation is required","Only for government contracts"]'::jsonb, 2, 4, true, 'advanced'),
  ('[SCENARIO] A company fails to publish details of its DPO on its website. Which obligation applies?', '["Notice obligation","Security obligation","DPO disclosure obligation","Consent withdrawal obligation"]'::jsonb, 2, 4, true, 'advanced'),
  ('[SCENARIO] A fiduciary does not verify age before processing children’s data. Is this compliant?', '["Yes, age verification is optional","Only for social media","No, reasonable verification is required","Only for foreign platforms"]'::jsonb, 2, 4, true, 'advanced'),
  ('[SCENARIO] A data fiduciary ignores DPB directions during inquiry. What is the implication?', '["No impact","Possible monetary penalty","Only warning issued","Only civil liability"]'::jsonb, 1, 4, true, 'advanced'),
  ('[SCENARIO] A company does not document its data protection measures. Is this compliant?', '["Yes, documentation is optional","Only required after breach","No, accountability requires documentation","Only for government bodies"]'::jsonb, 2, 4, true, 'advanced'),
  ('What is the penalty for failure to implement reasonable security safeguards?', '["₹50 crore","Up to ₹250 crore","₹10 crore","No specific penalty"]'::jsonb, 1, 4, false, 'intermediate'),
  ('What is the penalty for failure to notify a breach to the Board or Data Principals?', '["₹100 crore","Up to ₹200 crore","₹50 crore","Warning only"]'::jsonb, 1, 4, false, 'intermediate'),
  ('[SCENARIO] A healthcare provider suffers a ransomware attack exposing patient records but delays notification to the Board by 45 days fearing reputational damage. What are the consequences?', '["Only a warning for first offense","Penalty up to ₹200 crore for breach notification failure, plus penalties for security safeguard failures","No consequence if data is eventually recovered","Penalty waived if ransom is paid"]'::jsonb, 1, 4, true, 'advanced'),
  ('What is the penalty for processing children''s personal data in contravention of Section 9?', '["₹50 crore","Up to ₹200 crore","₹100 crore","Warning only"]'::jsonb, 1, 4, false, 'intermediate'),
  ('Can criminal prosecution be initiated for DPDPA violations?', '["Yes, for all violations","No, DPDPA provides only civil penalties through the Board","Only for breaches affecting > 1 million users","Only if approved by Supreme Court"]'::jsonb, 1, 4, false, 'intermediate'),
  ('What is the enforcement timeline prescribed in the DPDP Rules 2025?', '["Immediate from notification date","Sections 3-17 (core provisions) by May 13, 2027 (18 months)","Full enforcement from January 1, 2030","No specific timeline"]'::jsonb, 1, 4, false, 'intermediate'),
  ('[SCENARIO] A startup incorporated in 2026 claims DPDPA doesn''t apply to it because it wasn''t registered when the Act was passed. Is this correct?', '["Yes, only entities existing in 2023 are covered","No, DPDPA applies to all entities processing personal data after enforcement dates, regardless of incorporation date","Yes, 5-year grandfather clause exists","Only if revenue exceeds threshold"]'::jsonb, 1, 4, true, 'advanced'),
  ('In data mapping, what does RoPA stand for?', '["Record of Processing Activities","Register of Personal Attributes","Record of Privacy Assessments","Register of Processing Authorities"]'::jsonb, 0, 5, false, 'advanced'),
  ('What are the 5 essential elements of valid consent under Section 6 of DPDPA?', '["Written, Documented, Archived, Revocable, Specific","Free, Specific, Informed, Unambiguous, Withdrawable","Explicit, Granular, Time-bound, Renewable, Recorded","Voluntary, Clear, Documented, Limited, Revocable"]'::jsonb, 1, 5, false, 'advanced'),
  ('In a consent register, which of these fields is most critical for DPDPA compliance?', '["IP address of user","Timestamp and withdrawal capability","Device fingerprint","Browser type"]'::jsonb, 1, 5, false, 'advanced'),
  ('[SCENARIO] You are building a consent management system for an e-commerce platform. Which feature is mandatory under DPDPA?', '["Biometric authentication for consent","Ability to withdraw consent as easily as it was given","Consent valid for lifetime by default","Consent stored only locally on user device"]'::jsonb, 1, 5, true, 'advanced'),
  ('Under Rule 13, when is a Data Protection Impact Assessment (DPIA) mandatory?', '["For all data processing activities","Only for cross-border transfers","For Significant Data Fiduciaries processing certain data","When processing more than 1 million records"]'::jsonb, 2, 5, false, 'advanced'),
  ('In a risk assessment matrix, what is typically a ''High Risk'' score range?', '["1-4","5-9","10-15","16-25"]'::jsonb, 2, 5, false, 'advanced'),
  ('[SCENARIO] A company fails to implement reasonable security safeguards leading to a major breach. What is the likely consequence under DPDPA?', '["Criminal prosecution of directors","Warning only","Monetary penalty imposed by the Data Protection Board","Immediate shutdown of business"]'::jsonb, 2, 5, true, 'advanced'),
  ('[SCENARIO] A data fiduciary repeatedly ignores directions issued by the Data Protection Board. What action can be taken?', '["Only advisory notice","Imposition of monetary penalty","Civil imprisonment","Automatic license cancellation"]'::jsonb, 1, 5, true, 'advanced'),
  ('[SCENARIO] A Significant Data Fiduciary fails to appoint a Data Protection Officer despite notification. What follows?', '["No action unless breach occurs","Only public warning","Penalty as prescribed under the Act","Criminal FIR registration"]'::jsonb, 2, 5, true, 'advanced'),
  ('[SCENARIO] A company delays breach notification causing harm to users. Which enforcement mechanism applies?', '["Adjudication by Data Protection Board","Civil court suit only","Criminal prosecution under IPC","Consumer court action"]'::jsonb, 0, 5, true, 'advanced'),
  ('[SCENARIO] A data fiduciary violates multiple provisions in a single incident. How are penalties determined?', '["One penalty per incident","Highest penalty only","Separate penalties for each violation","No penalty for first offence"]'::jsonb, 2, 5, true, 'advanced'),
  ('[SCENARIO] A startup argues inability to pay penalty due to financial hardship. Is this a valid defence?', '["Yes, hardship exempts liability","Only for MSMEs","No, financial status does not negate liability","Only for first-time offenders"]'::jsonb, 2, 5, true, 'advanced'),
  ('[SCENARIO] A company challenges a penalty imposed by the Data Protection Board. Where can it appeal?', '["High Court directly","Supreme Court","Telecom Disputes Settlement Appellate Tribunal","Consumer Forum"]'::jsonb, 2, 5, true, 'advanced'),
  ('[SCENARIO] A data fiduciary provides false information during a DPB inquiry. What is the consequence?', '["No consequence","Reduced penalty","Higher penalty for non-cooperation","Only written warning"]'::jsonb, 2, 5, true, 'advanced'),
  ('[SCENARIO] A breach occurs despite best security measures. Is penalty automatic?', '["Yes, strict liability applies","No, DPB considers mitigating factors","Only for significant fiduciaries","Only if harm is proven"]'::jsonb, 1, 5, true, 'advanced'),
  ('[SCENARIO] A company fails to comply with DPB summons. What power does the Board have?', '["Arrest powers","Impose monetary penalty","Issue criminal warrant","Cancel company registration"]'::jsonb, 1, 5, true, 'advanced'),
  ('[SCENARIO] Can compensation be awarded to Data Principals under DPDPA?', '["Yes, by the DPB","Yes, by civil courts","No, DPDPA provides penalties, not compensation","Only by Supreme Court"]'::jsonb, 2, 5, true, 'advanced'),
  ('[SCENARIO] A company commits the same violation multiple times. How does DPB respond?', '["Issue only warnings","Ignore repeat offences","Consider aggravating factors for higher penalty","Bar business operations permanently"]'::jsonb, 2, 5, true, 'advanced'),
  ('[SCENARIO] A fiduciary claims lack of awareness of DPDPA provisions. Is ignorance a defence?', '["Yes, for first year","Only for small companies","No, ignorance of law is not a defence","Only if disclosure was absent"]'::jsonb, 2, 5, true, 'advanced'),
  ('[SCENARIO] A data processor is responsible for breach caused by its negligence. Who is penalised?', '["Only processor","Only fiduciary","Both may be held accountable","Neither"]'::jsonb, 2, 5, true, 'advanced'),
  ('[SCENARIO] What is the maximum penalty that can be imposed under DPDPA?', '["₹100 crore","₹250 crore","₹500 crore","Unlimited"]'::jsonb, 2, 5, true, 'advanced'),
  ('[SCENARIO] Can DPB initiate action without a complaint from a Data Principal?', '["No, complaint is mandatory","Yes, Board can act suo motu","Only with court direction","Only for government entities"]'::jsonb, 1, 5, true, 'advanced'),
  ('[SCENARIO] A company settles grievance but violation already occurred. Can DPB still impose penalty?', '["No, settlement bars penalty","Only if user insists","Yes, regulatory action is independent","Only for significant fiduciaries"]'::jsonb, 2, 5, true, 'advanced'),
  ('[SCENARIO] A fiduciary voluntarily reports a breach promptly. How does DPB treat this?', '["Mandatory maximum penalty","No inquiry conducted","As a mitigating factor","As an admission of guilt only"]'::jsonb, 2, 5, true, 'advanced'),
  ('[SCENARIO] A company fails to pay imposed penalty within stipulated time. What can follow?', '["No further action","Recovery proceedings as per law","Automatic imprisonment","Immediate shutdown"]'::jsonb, 1, 5, true, 'advanced'),
  ('[SCENARIO] A Data Principal files a frivolous complaint. What power does DPB have?', '["Ignore complaint","Penalise the Data Principal","Refer matter to police","Mandate mediation"]'::jsonb, 1, 5, true, 'advanced'),
